html:
{%- set company_doc = frappe.get_doc("Company", doc.company) -%}
{%- macro vnd(amount) -%}{{ "{:,.0f}".format(amount or 0).replace(",", ".") }}{%- endmacro -%}
{%- set d = frappe.utils.getdate(doc.disposal_date) -%}
{%- set buyer_name = frappe.db.get_value("Customer", doc.buyer, "customer_name") if doc.buyer else "" -%}

<style>
@media print {
    @page { size: A4 portrait; margin: 20mm 15mm; }
}
.ad-print a {
    color: inherit !important;
    text-decoration: none !important;
}
.ad-print {
    font-family: "Times New Roman", Times, serif;
    font-size: 13px;
    line-height: 1.6;
    max-width: 700px;
    margin: 0 auto;
}
.ad-print .header-national {
    text-align: center;
    font-weight: bold;
    text-transform: uppercase;
    margin-bottom: 5px;
}
.ad-print .header-motto {
    text-align: center;
    font-style: italic;
    margin-bottom: 20px;
}
.ad-print h2 {
    text-align: center;
    font-size: 16px;
    font-weight: bold;
    text-transform: uppercase;
    margin: 15px 0 5px;
}
.ad-print .doc-number {
    text-align: center;
    margin-bottom: 5px;
}
.ad-print .doc-date {
    text-align: center;
    font-style: italic;
    margin-bottom: 15px;
}
.ad-print .section-title {
    font-weight: bold;
    margin-top: 12px;
}
.ad-print table.info-table {
    width: 100%;
    border-collapse: collapse;
    margin: 8px 0;
}
.ad-print table.info-table td {
    padding: 3px 8px;
    vertical-align: top;
}
.ad-print table.info-table td:first-child {
    width: 35%;
    font-weight: normal;
}
.ad-print .sig-table {
    width: 100%;
    margin-top: 40px;
}
.ad-print .sig-table td {
    text-align: center;
    vertical-align: top;
    padding: 5px 10px;
    width: 33%;
}
.ad-print .sig-table .sig-title { font-weight: bold; }
.ad-print .sig-table .sig-note { font-style: italic; font-size: 12px; }
.ad-print .sig-table .sig-name { margin-top: 60px; font-weight: bold; }
</style>

<div class="ad-print">
    <div class="header-national">C&#7897;ng h&ograve;a x&atilde; h&#7897;i ch&#7911; ngh&#297;a Vi&#7879;t Nam</div>
    <div class="header-motto">&#272;&#7897;c l&#7853;p - T&#7921; do - H&#7841;nh ph&uacute;c</div>

    <h2>Bi&ecirc;n b&#7843;n thanh l&yacute; t&agrave;i s&#7843;n c&#7889; &#273;&#7883;nh</h2>
    <div class="doc-number">S&#7889;: {{ doc.name }}</div>
    <div class="doc-date">Ng&agrave;y {{ d.day }} th&aacute;ng {{ d.month }} n&#259;m {{ d.year }}</div>

    <div>C&#259;n c&#7913; Quy&#7871;t &#273;&#7883;nh s&#7889; ......... ng&agrave;y ......... c&#7911;a {{ company_doc.company_name }}</div>
    <div>v&#7873; vi&#7879;c thanh l&yacute; t&agrave;i s&#7843;n c&#7889; &#273;&#7883;nh.</div>

    {% if doc.participants %}
    <div class="section-title">I. Th&agrave;nh ph&#7847;n tham gia:</div>
    <table class="info-table">
        {% for p in doc.participants %}
        <tr><td>{{ loop.index }}. {{ p.employee_name }}</td><td>{{ p.designation or '' }}{% if p.department %} - {{ p.department }}{% endif %}</td></tr>
        {% endfor %}
    </table>
    {% endif %}

    <div class="section-title">{% if doc.participants %}II{% else %}I{% endif %}. Th&ocirc;ng tin t&agrave;i s&#7843;n:</div>
    <table class="info-table">
        <tr><td>- T&ecirc;n t&agrave;i s&#7843;n:</td><td>{{ doc.asset_name }}</td></tr>
        <tr><td>- M&atilde; t&agrave;i s&#7843;n:</td><td>{{ doc.asset }}</td></tr>
        <tr><td>- Nh&oacute;m TSCD:</td><td>{{ doc.asset_category }}</td></tr>
        <tr><td>- Nguy&ecirc;n gi&aacute;:</td><td>{{ vnd(doc.gross_purchase_amount) }} VND</td></tr>
        <tr><td>- Gi&aacute; tr&#7883; hao m&ograve;n l&#361;y k&#7871;:</td><td>{{ vnd(doc.accumulated_depreciation) }} VND</td></tr>
        <tr><td>- Gi&aacute; tr&#7883; c&ograve;n l&#7841;i:</td><td>{{ vnd(doc.book_value) }} VND</td></tr>
    </table>

    <div class="section-title">{% if doc.participants %}III{% else %}II{% endif %}. H&igrave;nh th&#7913;c thanh l&yacute;: {% if doc.disposal_type == "Sell" %}B&aacute;n{% else %}H&#7911;y{% endif %}</div>
    {% if doc.disposal_type == "Sell" %}
    <table class="info-table">
        <tr><td>- Gi&aacute; b&aacute;n:</td><td>{{ vnd(doc.selling_amount) }} VND</td></tr>
        <tr><td>- Ng&#432;&#7901;i mua:</td><td>{{ buyer_name }}</td></tr>
    </table>
    {% endif %}

    {% if doc.disposal_reason %}
    <div class="section-title">{% if doc.participants %}IV{% else %}III{% endif %}. L&yacute; do thanh l&yacute;:</div>
    <div style="white-space: pre-line;">{{ doc.disposal_reason }}</div>
    {% endif %}

    <div class="section-title">K&#7871;t lu&#7853;n:</div>
    <div>H&#7897;i &#273;&#7891;ng thanh l&yacute; &#273;&atilde; ti&#7871;n h&agrave;nh thanh l&yacute; t&agrave;i s&#7843;n theo &#273;&uacute;ng quy &#273;&#7883;nh.</div>

    <table class="sig-table">
        <tr>
            <td class="sig-title">K&#7871; to&aacute;n tr&#432;&#7903;ng</td>
            <td class="sig-title">H&#7897;i &#273;&#7891;ng thanh l&yacute;</td>
            <td class="sig-title">Gi&aacute;m &#273;&#7889;c</td>
        </tr>
        <tr>
            <td class="sig-note">(K&yacute;, h&#7885; t&ecirc;n)</td>
            <td class="sig-note">(K&yacute;, h&#7885; t&ecirc;n)</td>
            <td class="sig-note">(K&yacute;, h&#7885; t&ecirc;n)</td>
        </tr>
        <tr>
            <td class="sig-name">&nbsp;</td>
            <td class="sig-name">&nbsp;</td>
            <td class="sig-name">&nbsp;</td>
        </tr>
    </table>
</div>
